"""Runs the three AI-course experiments and writes results.json next to this file."""

import json
import platform
from pathlib import Path

import csp_consistency
import ocr_search
import quality_tree

if __name__ == "__main__":
    results = {
        "note": "All inputs are synthetic and generated by these scripts. No certificate data is used.",
        "python": platform.python_version(),
        "csp_field_consistency": csp_consistency.run_experiment(),
        "ocr_correction_search": ocr_search.run_experiment(),
        "capture_quality_decision_tree": quality_tree.run_experiment(),
    }
    out = Path(__file__).with_name("results.json")
    out.write_text(json.dumps(results, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {out}")
